const config = $node["Repository Config"].json;
const owner = config.owner;
const repo = config.repo;
const since = config.since;
const until = config.until;
const headers = {
  Accept: "application/vnd.github+json",
  "X-GitHub-Api-Version": "2022-11-28",
};
if ($env.GITHUB_TOKEN) {
  headers.Authorization = `Bearer ${$env.GITHUB_TOKEN}`;
}
async function github(path) {
  const response = await fetch(`https://api.github.com/repos/${owner}/${repo}${path}`, { headers });
  if (!response.ok) {
    throw new Error(`GitHub API ${response.status}: ${await response.text()}`);
  }
  return await response.json();
}
const [commits, closedIssuesRaw, closedPrsRaw] = await Promise.all([
  github(`/commits?since=${encodeURIComponent(since)}&until=${encodeURIComponent(until)}&per_page=100`),
  github(`/issues?state=closed&since=${encodeURIComponent(since)}&per_page=100`),
  github(`/pulls?state=closed&sort=updated&direction=desc&per_page=100`),
]);
const windowStart = new Date(since);
const closedIssues = closedIssuesRaw.filter(issue => !issue.pull_request);
const mergedPrs = closedPrsRaw.filter(pr => pr.merged_at && new Date(pr.merged_at) >= windowStart);
const activity = {
  repository: `${owner}/${repo}`,
  window: { since, until },
  commits: commits.map(commit => ({
    sha: commit.sha?.slice(0, 7),
    message: commit.commit?.message?.split("\n")[0],
    author: commit.commit?.author?.name,
    date: commit.commit?.author?.date,
    url: commit.html_url
  })),
  closedIssues: closedIssues.map(issue => ({
    number: issue.number,
    title: issue.title,
    closedBy: issue.closed_by?.login,
    closedAt: issue.closed_at,
    url: issue.html_url
  })),
  mergedPrs: mergedPrs.map(pr => ({
    number: pr.number,
    title: pr.title,
    author: pr.user?.login,
    mergedAt: pr.merged_at,
    url: pr.html_url
  }))
};
const languageInstruction = config.language === "FR"
  ? "Write the summary in French."
  : "Write the summary in English.";
return [{
  json: {
    activity,
    claudeRequest: {
      model: "claude-sonnet-4-20250514",
      max_tokens: 1200,
      temperature: 0.2,
      messages: [
        {
          role: "user",
          content: `You are generating a weekly narrative development summary for ${activity.repository}. ${languageInstruction}\n\nUse this JSON activity data to write:\n1. A 2-3 sentence executive summary\n2. Merged PR highlights\n3. Closed issue highlights\n4. Commit trends\n5. Suggested follow-ups for next week\n\nKeep it concise and specific.\n\nActivity JSON:\n${JSON.stringify(activity, null, 2)}`
        }
      ]
    }
  }
}];

const response = $input.first().json;
const config = $node["Repository Config"].json;
const text = response.content?.map(part => part.text).filter(Boolean).join("\n\n") || "No summary text returned from Claude.";
return [{
  json: {
    summary: text,
    slackPayload: {
      text: `Weekly development summary for ${config.owner}/${config.repo}`,
      blocks: [
        {
          type: "header",
          text: { type: "plain_text", text: `Weekly summary: ${config.owner}/${config.repo}` }
        },
        {
          type: "section",
          text: { type: "mrkdwn", text }
        }
      ]
    }
  }
}];
